namespace sv_506be8385c4c47afb55cdc74bea70e4e.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — one instance per circuit, so each user gets independent state.
/// Interactive island components subscribe to <see cref="OnThemeChanged"/> to
/// re-render when any component mutates the theme.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _mode = ThemeMode.System;
    private string _accentColor = "#0d6efd"; // Bootstrap primary blue

    public ThemeMode Mode
    {
        get => _mode;
        set
        {
            if (_mode == value) return;
            _mode = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised on the circuit's synchronization context, so subscribers can
    /// safely call <c>StateHasChanged</c> without <c>InvokeAsync</c>.
    /// </summary>
    public event Action? OnThemeChanged;

    /// <summary>
    /// Bulk-update both values with a single notification.
    /// </summary>
    public void SetTheme(ThemeMode mode, string accentColor)
    {
        _mode = mode;
        _accentColor = accentColor;
        NotifyChanged();
    }

    private void NotifyChanged() => OnThemeChanged?.Invoke();
}

@* Interactive island that lives in the static MainLayout header.
   Because it has @rendermode InteractiveServer, it joins the circuit
   and shares the same scoped ThemeService as every other interactive
   component on the page. *@

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService Theme

<span class="badge rounded-pill @BadgeClass" title="Current theme: @Theme.Mode">
    @Icon @Theme.Mode
</span>

@code {
    private string BadgeClass => Theme.Mode switch
    {
        ThemeMode.Dark  => "text-bg-dark",
        ThemeMode.Light => "text-bg-warning",
        _               => "text-bg-secondary"
    };

    private string Icon => Theme.Mode switch
    {
        ThemeMode.Dark  => "🌙",
        ThemeMode.Light => "☀️",
        _               => "💻"
    };

    protected override void OnInitialized()
        => Theme.OnThemeChanged += StateHasChanged;

    public void Dispose()
        => Theme.OnThemeChanged -= StateHasChanged;
}

@* Quick toggle button — can be placed in the sidebar, header, or any page. *@

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService Theme

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
        title="Switch theme">
    @Icon
</button>

@code {
    private string Icon => Theme.Mode switch
    {
        ThemeMode.Dark  => "🌙",
        ThemeMode.Light => "☀️",
        _               => "💻"
    };

    private void CycleTheme()
    {
        Theme.Mode = Theme.Mode switch
        {
            ThemeMode.Light  => ThemeMode.Dark,
            ThemeMode.Dark   => ThemeMode.System,
            _                => ThemeMode.Light
        };
    }

    protected override void OnInitialized()
        => Theme.OnThemeChanged += StateHasChanged;

    public void Dispose()
        => Theme.OnThemeChanged -= StateHasChanged;
}

@* Full preferences panel used on the /settings page. *@

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService Theme

<div class="card" style="border-color: @Theme.AccentColor">
    <div class="card-header" style="background-color: @Theme.AccentColor; color: white;">
        User Preferences
    </div>
    <div class="card-body">
        <div class="mb-3">
            <label class="form-label fw-bold">Theme Mode</label>
            <div class="btn-group d-flex" role="group">
                @foreach (var mode in Enum.GetValues<ThemeMode>())
                {
                    var active = mode == Theme.Mode;
                    <button type="button"
                            class="btn @(active ? "btn-primary" : "btn-outline-primary")"
                            style="@(active ? $"background-color:{Theme.AccentColor};border-color:{Theme.AccentColor}" : "")"
                            @onclick="() => Theme.Mode = mode">
                        @mode
                    </button>
                }
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label fw-bold" for="accentPicker">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color" id="accentPicker" class="form-control form-control-color"
                       value="@Theme.AccentColor"
                       @onchange="OnAccentChanged" />
                <code>@Theme.AccentColor</code>
            </div>
        </div>

        <div class="alert alert-info mb-0">
            Changes are applied instantly to all components in your session.
        </div>
    </div>
</div>

@code {
    private void OnAccentChanged(ChangeEventArgs e)
    {
        if (e.Value is string color && color.StartsWith('#'))
            Theme.AccentColor = color;
    }

    protected override void OnInitialized()
        => Theme.OnThemeChanged += StateHasChanged;

    public void Dispose()
        => Theme.OnThemeChanged -= StateHasChanged;
}

